16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.HashUtils;
20	import org.springframework.samples.petclinic.util.TelephoneFormatter;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.time.Period;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "address_line1")
49	    private String addressLine1;
50	
51	    @Column(name = "address_line2")
52	    private String addressLine2;
53	
54	    @Column(name = "city")
55	    @NotEmpty
56	    private String city;
57	
58	    @Column(name = "telephone")
59	    @NotEmpty
60	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
61	    private String telephone;
62	
63	    @Column(name = "email")
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "registration_date", columnDefinition = "DATE")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date", columnDefinition = "DATE")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "possible_duplicate")
85	    private Boolean possibleDuplicate;
86	
87	    @Column(name = "possible_duplicate_of")
88	    private Integer possibleDuplicateOf;
89	
90	    @Column(name = "deleted")
91	    private Boolean deleted = false;
92	
93	    @Column(name = "membership_level")
94	    private Integer membershipLevel;
95	
96	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
97	    private Set<Pet> pets;
98	
99	    public String getTitle() {
100	        return this.title;
101	    }
102	
103	    public void setTitle(String title) {
104	        this.title = title;
105	    }
106	
107	    public String getAddress() {
108	        return this.address;
109	    }
110	
111	    public void setAddress(String address) {
112	        this.address = address;
113	    }
114	
115	    public String getAddressLine1() {
116	        return this.addressLine1;
117	    }
118	
119	    public void setAddressLine1(String addressLine1) {
120	        this.addressLine1 = addressLine1;
121	    }
122	
123	    public String getAddressLine2() {
124	        return this.addressLine2;
125	    }
126	
127	    public void setAddressLine2(String addressLine2) {
128	        this.addressLine2 = addressLine2;
129	    }
130	
131	    public String getCity() {
132	        return this.city;
133	    }
134	
135	    public void setCity(String city) {
136	        this.city = city;
137	    }
138	
139	    public String getTelephone() {
140	        return this.telephone;
141	    }
142	
143	    public void setTelephone(String telephone) {
144	        this.telephone = telephone;
145	    }
146	
147	    /**
148	     * The stored E.164 {@code telephone} formatted for humans (e.g. {@code '+61 412 345 678'} for the
149	     * stored {@code '+61412345678'}); the raw {@code telephone} stays in E.164 form. Derived from the
150	     * owner's own {@code telephone}; see {@link TelephoneFormatter#toDisplay(String)}.
151	     */
152	    @Transient
153	    public String getTelephoneDisplay() {
154	        return TelephoneFormatter.toDisplay(this.telephone);
155	    }
156	
157	    public String getEmail() {
158	        return this.email;
159	    }
160	
161	    public void setEmail(String email) {
162	        this.email = email;
163	    }
164	
165	    public String getPostcode() {
166	        return this.postcode;
167	    }
168	
169	    public void setPostcode(String postcode) {
170	        this.postcode = postcode;
171	    }
172	
173	    public LocalDate getRegistrationDate() {
174	        return this.registrationDate;
175	    }
176	
177	    public void setRegistrationDate(LocalDate registrationDate) {
178	        this.registrationDate = registrationDate;
179	    }
180	
181	    public LocalDate getBirthDate() {
182	        return this.birthDate;
183	    }
184	
185	    public void setBirthDate(LocalDate birthDate) {
186	        this.birthDate = birthDate;
187	    }
188	
189	    public String getCustomerCode() {
190	        return this.customerCode;
191	    }
192	
193	    public void setCustomerCode(String customerCode) {
194	        this.customerCode = customerCode;
195	    }
196	
197	    public String getHouseholdId() {
198	        return this.householdId;
199	    }
200	
201	    public void setHouseholdId(String householdId) {
202	        this.householdId = householdId;
203	    }
204	
205	    public Integer getNamesakeCount() {
206	        return this.namesakeCount;
207	    }
208	
209	    public void setNamesakeCount(Integer namesakeCount) {
210	        this.namesakeCount = namesakeCount;
211	    }
212	
213	    /**
214	     * Whether this owner was flagged a possible (soft) duplicate at creation time: it was not a
215	     * hard duplicate, but its {@code soundex(lastName)} and postcode matched an existing owner's while
216	     * its identity key differed. {@code false} (or {@code null} for owners created before the check)
217	     * when no such match was found.
218	     */
219	    public Boolean getPossibleDuplicate() {
220	        return this.possibleDuplicate;
221	    }
222	
223	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
224	        this.possibleDuplicate = possibleDuplicate;
225	    }
226	
227	    /**
228	     * The id of the existing owner this one was flagged a possible duplicate of, or {@code null}
229	     * when {@code possibleDuplicate} is not set.
230	     */
231	    public Integer getPossibleDuplicateOf() {
232	        return this.possibleDuplicateOf;
233	    }
234	
235	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
236	        this.possibleDuplicateOf = possibleDuplicateOf;
237	    }
238	
239	    /**
240	     * Whether this owner has been soft-deleted. A newly created owner is {@code false}; the
241	     * {@code DELETE /api/owners/{id}} endpoint flags it {@code true} while retaining the record, and
242	     * the create endpoint's duplicate and identity checks ignore owners flagged deleted. Treated as
243	     * {@code false} when {@code null} (owners persisted before the column existed).
244	     */
245	    public Boolean getDeleted() {
246	        return this.deleted != null && this.deleted;
247	    }
248	
249	    public void setDeleted(Boolean deleted) {
250	        this.deleted = deleted;
251	    }
252	
253	    /**
254	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
255	     */
256	    @Transient
257	    public String getDisplayName() {
258	        return this.getLastName() + ", " + this.getFirstName();
259	    }
260	
261	    /**
262	     * The owner's salutation: the honorific {@link #getTitle() title} and the last name separated by
263	     * a single space (e.g. {@code 'DR who'}), or just the last name when the owner has no title.
264	     * Derived from the owner's own fields.
265	     */
266	    @Transient
267	    public String getSalutation() {
268	        if (this.title == null || this.title.isBlank()) {
269	            return this.getLastName();
270	        }
271	        return this.title + " " + this.getLastName();
272	    }
273	
274	    /**
275	     * The owner's initials: the upper-cased first letters of the first and last name,
276	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
277	     */
278	    @Transient
279	    public String getInitials() {
280	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
281	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
282	    }
283	
284	    /**
285	     * The fiscal year a date falls in. The fiscal year starts on 1 July and is identified by the
286	     * calendar year in which it ends: a date in July through December belongs to the fiscal year
287	     * ending the following calendar year, a date in January through June to the fiscal year ending
288	     * that same calendar year.
289	     */
290	    private static int fiscalYearOf(LocalDate date) {
291	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
292	    }
293	
294	    /**
295	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the last two digits of
296	     * the fiscal year (which starts on 1 July) that the business-day-adjusted {@code registrationDate}
297	     * falls in (e.g. {@code 'FY26'} for a registration date between 1 July 2025 and 30 June 2026).
298	     * Derived from the owner's own {@code registrationDate}; {@code null} until it is set.
299	     */
300	    @Transient
301	    public String getFiscalYear() {
302	        if (this.registrationDate == null) {
303	            return null;
304	        }
305	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
306	    }
307	
308	    /**
309	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
310	     * the last two digits of the fiscal year carried by the business-day-adjusted registration date
311	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived from the owner's own fields; {@code null} until both
312	     * the customer code and registration date are set.
313	     */
314	    @Transient
315	    public String getMembershipNumber() {
316	        if (this.customerCode == null || this.registrationDate == null) {
317	            return null;
318	        }
319	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
320	    }
321	
322	    /**
323	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
324	     * {@code customerCode}. Derived from the owner's own fields; {@code null} until the customer
325	     * code is set. The standard Luhn algorithm is applied to the digits of the customer code, from
326	     * right to left, doubling every second digit (subtracting 9 when the doubled value exceeds 9).
327	     */
328	    @Transient
329	    public Integer getCheckDigit() {
330	        if (this.customerCode == null) {
331	            return null;
332	        }
333	        int sum = 0;
334	        boolean dbl = true;
335	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
336	            char c = this.customerCode.charAt(i);
337	            if (c < '0' || c > '9') {
338	                continue;
339	            }
340	            int d = c - '0';
341	            if (dbl) {
342	                d *= 2;
343	                if (d > 9) {
344	                    d -= 9;
345	                }
346	            }
347	            sum += d;
348	            dbl = !dbl;
349	        }
350	        return (10 - (sum % 10)) % 10;
351	    }
352	
353	    /**
354	     * The owner's membership points, a score accumulated from the owner's own fields. It starts at
355	     * 0 and gains: 2 when the owner has an email address; 1 when the owner is unique
356	     * ({@code namesakeCount} is 0); 2 when the owner belongs to a household of 3 or more members
357	     * (the owner together with their pets); and 3 when the owner's tenure spans at least one elapsed
358	     * fiscal year, measured as the difference between the fiscal year of today and the fiscal year of
359	     * {@code registrationDate}. Because a newly created owner has zero elapsed fiscal years of tenure,
360	     * a new owner never earns the tenure points. The score feeds {@link #getMembershipLevel()}.
361	     */
362	    @Transient
363	    public Integer getMembershipPoints() {
364	        int points = 0;
365	        boolean hasEmail = this.email != null && !this.email.isBlank();
366	        if (hasEmail) {
367	            points += 2;
368	        }
369	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
370	        if (unique) {
371	            points += 1;
372	        }
373	        int householdSize = 1 + getPetsInternal().size();
374	        if (householdSize >= 3) {
375	            points += 2;
376	        }
377	        boolean tenured = this.registrationDate != null
378	            && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) > 0;
379	        if (tenured) {
380	            points += 3;
381	        }
382	        return points;
383	    }
384	
385	    /**
386	     * The owner's numeric membership level, from 1 to 4. By default it is derived from
387	     * {@link #getMembershipPoints()}: level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and
388	     * 4 for 6 or more points. When a level has been assigned and stored at creation time (the capped
389	     * level computed against the owner's household), that stored value is returned instead, so the
390	     * level read back for the owner reflects the household ceiling applied when the owner was created.
391	     */
392	    @Transient
393	    public Integer getMembershipLevel() {
394	        if (this.membershipLevel != null) {
395	            return this.membershipLevel;
396	        }
397	        return getDerivedMembershipLevel();
398	    }
399	
400	    /**
401	     * Stores the owner's membership level, overriding the value otherwise derived from the owner's
402	     * membership points. Used at creation time to persist the household-capped level.
403	     */
404	    public void setMembershipLevel(Integer membershipLevel) {
405	        this.membershipLevel = membershipLevel;
406	    }
407	
408	    /**
409	     * The owner's membership level derived purely from {@link #getMembershipPoints()}, before any
410	     * household cap: level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more
411	     * points.
412	     */
413	    @Transient
414	    public Integer getDerivedMembershipLevel() {
415	        int points = getMembershipPoints();
416	        if (points >= 6) {
417	            return 4;
418	        }
419	        if (points >= 4) {
420	            return 3;
421	        }
422	        if (points >= 2) {
423	            return 2;
424	        }
425	        return 1;
426	    }
427	
428	    /**
429	     * The owner's locality: the canonical region carried by the {@code customerCode}, which is the
430	     * {@code <REGION>} segment preceding its first {@code '-'} (e.g. {@code 'NSW'} for customer code
431	     * {@code 'NSW-1A2B3C4D'}). The region is the one derived from the postcode at creation time and
432	     * baked into the identity. {@code 'UNKNOWN'} when the owner has no customer code yet.
433	     */
434	    @Transient
435	    public String getLocality() {
436	        if (this.customerCode == null) {
437	            return "UNKNOWN";
438	        }
439	        int dash = this.customerCode.indexOf('-');
440	        return dash < 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
441	    }
442	
443	    /**
444	     * Fixed region-to-timezone lookup mapping each canonical region to its IANA timezone name:
445	     * {@code NSW -> 'Australia/Sydney'}, {@code VIC -> 'Australia/Melbourne'},
446	     * {@code QLD -> 'Australia/Brisbane'}.
447	     */
448	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
449	        "NSW", "Australia/Sydney",
450	        "VIC", "Australia/Melbourne",
451	        "QLD", "Australia/Brisbane");
452	
453	    /**
454	     * The owner's timezone: the IANA name derived from the owner's {@link #getLocality() locality}
455	     * via the fixed region-to-timezone table ({@code NSW -> 'Australia/Sydney'},
456	     * {@code VIC -> 'Australia/Melbourne'}, {@code QLD -> 'Australia/Brisbane'}). {@code null} when
457	     * the locality is not one of these regions.
458	     */
459	    @Transient
460	    public String getTimezone() {
461	        return REGION_TIMEZONE.get(getLocality());
462	    }
463	
464	    /**
465	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
466	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. The
467	     * {@code <TIER>} is {@code 'PREMIUM'} when the owner's {@link #getMembershipLevel() membership
468	     * level} is 3 or more, otherwise {@code 'STANDARD'}. The {@code <AREA>} is {@code 'METRO'} when
469	     * the owner's {@link #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
470	     * {@code 'REGIONAL'}. Derived from the owner's own fields.
471	     */
472	    @Transient
473	    public String getOwnerSegment() {
474	        Integer level = getMembershipLevel();
475	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
476	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
477	        return tier + "_" + area;
478	    }
479	
480	    /**
481	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
482	     * the lower-case hex SHA-256 digest of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}.
483	     * The telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
484	     * owner has none), and the final segment the American Soundex code of the owner's last name. Two
485	     * owners are duplicates only when their whole identity keys are equal; because the telephone is
486	     * part of the key, two owners with the same last name and postcode but different telephones have
487	     * different identity keys and are not hard duplicates.
488	     */
489	    @Transient
490	    public String getIdentityKey() {
491	        String telephonePart = this.telephone == null ? "" : this.telephone;
492	        String emailPart = this.email == null ? "" : this.email;
493	        String soundexPart = soundex(this.getLastName());
494	        return HashUtils.sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
495	    }
496	
497	    /**
498	     * The American Soundex code of the owner's last name, used to group similar-sounding surnames for
499	     * soft (possible-duplicate) matching. Derived from the owner's own last name.
500	     */
501	    @Transient
502	    public String getLastNameSoundex() {
503	        return soundex(this.getLastName());
504	    }
505	
506	    /**
507	     * Computes the American Soundex code of a name: its first letter (upper-cased) followed by three
508	     * digits derived from the remaining consonants, with adjacent duplicate codes (and codes separated
509	     * only by {@code H} or {@code W}) collapsed, then zero-padded and truncated to four characters. A
510	     * {@code null} or letter-free value yields an empty string.
511	     *
512	     * @param value the name to encode
513	     * @return the four-character Soundex code, or an empty string
514	     */
515	    private static String soundex(String value) {
516	        if (value == null) {
517	            return "";
518	        }
519	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
520	        if (letters.isEmpty()) {
521	            return "";
522	        }
523	        StringBuilder code = new StringBuilder();
524	        code.append(letters.charAt(0));
525	        char previousDigit = soundexDigit(letters.charAt(0));
526	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
527	            char c = letters.charAt(i);
528	            char digit = soundexDigit(c);
529	            if (digit != '0' && digit != previousDigit) {
530	                code.append(digit);
531	            }
532	            if (c != 'H' && c != 'W') {
533	                previousDigit = digit;
534	            }
535	        }
536	        while (code.length() < 4) {
537	            code.append('0');
538	        }
539	        return code.toString();
540	    }
541	
542	    /**
543	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for the vowels and the
544	     * letters {@code H}, {@code W} and {@code Y} that carry no Soundex digit.
545	     */
546	    private static char soundexDigit(char c) {
547	        switch (c) {
548	            case 'B': case 'F': case 'P': case 'V':
549	                return '1';
550	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
551	                return '2';
552	            case 'D': case 'T':
553	                return '3';
554	            case 'L':
555	                return '4';
556	            case 'M': case 'N':
557	                return '5';
558	            case 'R':
559	                return '6';
560	            default:
561	                return '0';
562	        }
563	    }
564	
565	    /**
566	     * The owner's preferred contact channel, derived from the owner's own fields:
567	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
568	     */
569	    @Transient
570	    public String getContactPreference() {
571	        boolean hasEmail = this.email != null && !this.email.isBlank();
572	        return hasEmail ? "EMAIL" : "PHONE";
573	    }
574	
575	    /**
576	     * The owner's age band, derived from the owner's own fields: the whole number of years from
577	     * {@code birthDate} to {@code registrationDate} placed into a band — {@code 'MINOR'} when under
578	     * 18, {@code 'ADULT'} when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is measured
579	     * as of the registration date rather than today, so the band is stable over time. {@code null}
580	     * when the owner has no birth date (or no registration date to measure against).
581	     */
582	    @Transient
583	    public String getAgeBand() {
584	        if (this.birthDate == null || this.registrationDate == null) {
585	            return null;
586	        }
587	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
588	        if (age < 18) {
589	            return "MINOR";
590	        }
591	        if (age < 65) {
592	            return "ADULT";
593	        }
594	        return "SENIOR";
595	    }
596	
597	    protected Set<Pet> getPetsInternal() {
598	        if (this.pets == null) {
599	            this.pets = new HashSet<>();
600	        }
601	        return this.pets;
602	    }
603	
604	    protected void setPetsInternal(Set<Pet> pets) {
605	        this.pets = pets;
606	    }
607	
608	    public List<Pet> getPets() {
609	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
610	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
611	        return Collections.unmodifiableList(sortedPets);
612	    }
613	
614	    public void setPets(List<Pet> pets) {
615	        this.pets = new HashSet<>(pets);
616	    }
617	
618	    public void addPet(Pet pet) {
619	        getPetsInternal().add(pet);
620	        pet.setOwner(this);
621	    }
622	
623	    /**
624	     * Return the Pet with the given name, or null if none found for this Owner.
625	     *
626	     * @param name to test
627	     * @return true if pet name is already in use
628	     */
629	    public Pet getPet(String name) {
630	        return getPet(name, false);
631	    }
632	
633	    /**
634	     * Return the Pet with the given name, or null if none found for this Owner.
635	     *
636	     * @param name to test
637	     * @return true if pet name is already in use
638	     */
639	    public Pet getPet(String name, boolean ignoreNew) {
640	        name = name.toLowerCase();
641	        for (Pet pet : getPetsInternal()) {
642	            if (!ignoreNew || !pet.isNew()) {
643	                String compName = pet.getName();
644	                compName = compName.toLowerCase();
645	                if (compName.equals(name)) {
646	                    return pet;
647	                }
648	            }
649	        }
650	        return null;
651	    }
652	
653	    public Pet getPet(Integer petId) {
654	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
655	    }
656	
657	    @Override
658	    public String toString() {
659	        return new ToStringCreator(this)
660	
661	            .append("id", this.getId())
662	            .append("new", this.isNew())
663	            .append("lastName", this.getLastName())
664	            .append("firstName", this.getFirstName())
665	            .append("address", this.address)
666	            .append("city", this.city)
667	            .append("telephone", this.telephone)
668	            .toString();
669	    }
670	}
