77	
78	    /**
79	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
80	     * domain containing at least one dot, with no whitespace in any part.
81	     */
82	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
83	
84	    /**
85	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email domain
86	     * (the part after the {@code @}, compared case-insensitively) is listed here is rejected: such
87	     * addresses are not durable contact details. Entries are stored lower-cased.
88	     */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
90	        "mailinator.com",
91	        "tempmail.com",
92	        "guerrillamail.com");
93	
94	    /**
95	     * Dedicated audit logger. On a successful owner create two records are emitted here: a
96	     * human-readable audit line carrying the new owner's id, customer code, registration date,
97	     * membership level and membership number, and — separately — an immutable structured
98	     * {@code OWNER_CREATED} event ({@link OwnerCreatedEvent}) serialized as JSON.
99	     */
100	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
101	
102	    /**
103	     * Serializer for the structured {@code OWNER_CREATED} audit event. A record's components are
104	     * emitted in declaration order, giving the event a stable field layout.
105	     */
106	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
107	
108	    /**
109	     * Monotonically increasing sequence stamped onto each structured {@code OWNER_CREATED} event. It
110	     * advances by one per emitted event across all creates for the application's lifetime, giving the
111	     * audit stream a total order independent of owner ids or timestamps.
112	     */
113	    private static final AtomicInteger OWNER_CREATED_SEQ = new AtomicInteger(0);
114	
115	    /**
116	     * Common street-type abbreviations expanded during address normalization. Keys are the
117	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
118	     * expanded form it is replaced with.
119	     */
120	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
121	        "ST", "STREET",
122	        "RD", "ROAD",
123	        "AVE", "AVENUE");
124	
125	    /**
126	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
127	     * is at capacity and cannot take any more.
128	     */
129	    private static final int CITY_CAPACITY = 50;
130	
131	    /**
132	     * The number of owners a city must already hold before a response starts carrying a
133	     * {@code capacityWarning}. Once a city holds at least this many owners (but still fewer than the
134	     * hard {@link #CITY_CAPACITY} limit), it is flagged as approaching capacity.
135	     */
136	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
137	
138	    /**
139	     * The maximum number of owners that may be registered in a single day. Once this many owners
140	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
141	     * owners can be created that day.
142	     */
143	    private static final int DAILY_OWNER_LIMIT = 100;
144	
145	    /**
146	     * The number of owners that may be registered on a single business day before a response starts
147	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
148	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
149	     * high volume.
150	     */
151	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
152	
153	    /**
154	     * Fixed public holidays that the business-day roll skips over. A registration date that lands on
155	     * one of these dates is rolled forward to the next non-holiday business day, exactly as a weekend
156	     * date is rolled forward off a Saturday or Sunday.
157	     */
158	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
159	        LocalDate.parse("2026-01-01"),
160	        LocalDate.parse("2026-01-26"),
161	        LocalDate.parse("2026-04-25"),
162	        LocalDate.parse("2026-12-25"),
163	        LocalDate.parse("2026-12-28"));
164	
165	    /**
166	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
167	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
168	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
169	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
170	     */
171	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
172	        "61", 9,
173	        "1", 10);
