274	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
275	        rejectDuplicateIdentity(owner);
276	        applyPossibleDuplicate(owner, sharesHousehold);
277	        owner.setRegistrationDate(registrationDate);
278	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
279	        owner.setCustomerCode(generateCustomerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
280	        owner.setMembershipLevel(cappedMembershipLevel(owner));
281	        this.clinicService.saveOwner(owner);
282	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
283	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
284	            owner.getMembershipLevel(), owner.getMembershipNumber());
285	        emitOwnerCreatedEvent(owner);
286	        rememberIdempotentCreate(idempotencyKey, owner.getId());
287	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
