295	    /**
296	     * Serves a repeated create that carries an {@code Idempotency-Key} already seen on an earlier
297	     * successful create. When the key has a remembered owner that still exists, the originally created
298	     * owner is returned with {@code 200 OK} (carrying its {@code Location}) so the retry neither creates
299	     * a duplicate nor re-runs the create rules. A {@code null} or blank key, an unseen key, or a key
300	     * whose owner no longer exists yields {@code null}, signalling the caller to perform a normal create.
301	     *
302	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
303	     * @return the originally created owner as a {@code 200 OK} response, or {@code null} to create normally
304	     */
305	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
306	        if (isBlank(idempotencyKey)) {
307	            return null;
308	        }
309	        Integer ownerId = idempotentCreateOwnerIds.get(idempotencyKey);
310	        if (ownerId == null) {
311	            return null;
312	        }
313	        Owner owner = this.clinicService.findOwnerById(ownerId);
314	        if (owner == null) {
315	            return null;
316	        }
317	        HttpHeaders headers = new HttpHeaders();
318	        headers.setLocation(UriComponentsBuilder.newInstance()
319	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
320	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
321	        applyBulkSignupWarning(ownerDto);
322	        applyCapacityWarning(ownerDto);
323	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.OK);
324	    }
