326	    /**
327	     * Remembers the owner just created under its request's {@code Idempotency-Key}, so a later create
328	     * repeating that key is served the same owner ({@link #replayIdempotentCreate}). A {@code null} or
329	     * blank key is ignored, leaving that create non-idempotent.
330	     *
331	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
332	     * @param ownerId        the id of the owner that was just created
333	     */
334	    private void rememberIdempotentCreate(String idempotencyKey, Integer ownerId) {
335	        if (!isBlank(idempotencyKey)) {
336	            idempotentCreateOwnerIds.put(idempotencyKey, ownerId);
337	        }
338	    }
