340	    /**
341	     * Emits the immutable structured {@code OWNER_CREATED} event for a freshly created owner on the
342	     * {@code AUDIT} logger, serialized as a JSON object {@code {seq, ownerId, customerCode,
343	     * membershipLevel, event}}. The {@code seq} is drawn from {@link #OWNER_CREATED_SEQ}, advancing by
344	     * one per create so the events carry a total order. The {@code customerCode} field carries the
345	     * owner's current primary identifier ({@link #primaryIdentifier}) — the customer code today — so
346	     * that when a later evolution unifies the customer code into the member id, the event tracks that
347	     * identifier with no change here.
348	     *
349	     * @param owner the owner that was just created and saved
350	     */
351	    private void emitOwnerCreatedEvent(Owner owner) {
352	        OwnerCreatedEvent event = new OwnerCreatedEvent(
353	            OWNER_CREATED_SEQ.incrementAndGet(),
354	            owner.getId(),
355	            primaryIdentifier(owner),
356	            owner.getMembershipLevel());
357	        AUDIT.info("{}", AUDIT_MAPPER.writeValueAsString(event));
358	    }
