360	    /**
361	     * Returns the owner's current primary identifier — the single value that externally names the
362	     * owner and is carried by the structured audit event. Today that is the {@code customerCode}; this
363	     * is the one place to change when a later evolution replaces it (for example when the customer code
364	     * is unified into the member id), so every consumer of the primary identifier follows automatically.
365	     *
366	     * @param owner the owner whose primary identifier is wanted
367	     * @return the owner's current primary identifier
368	     */
369	    private String primaryIdentifier(Owner owner) {
370	        return owner.getCustomerCode();
371	    }
