373	    /**
374	     * Immutable structured audit event emitted on a successful owner create. Serialized to JSON on the
375	     * {@code AUDIT} logger, its component order fixes the field order {@code {seq, ownerId,
376	     * customerCode, membershipLevel, event}}. The {@code event} discriminator is always
377	     * {@code 'OWNER_CREATED'}. The {@code customerCode} component holds the owner's current primary
378	     * identifier rather than necessarily the raw customer-code field, so the event follows the primary
379	     * identifier if a later evolution changes what that is.
380	     *
381	     * @param seq             monotonically increasing sequence across all creates
382	     * @param ownerId         the new owner's id
383	     * @param customerCode    the owner's current primary identifier
384	     * @param membershipLevel the owner's stored membership level
385	     */
386	    private record OwnerCreatedEvent(int seq, Integer ownerId, String customerCode, Integer membershipLevel,
387	                                     String event) {
388	        private OwnerCreatedEvent(int seq, Integer ownerId, String customerCode, Integer membershipLevel) {
389	            this(seq, ownerId, customerCode, membershipLevel, "OWNER_CREATED");
390	        }
391	    }
