551	    /**
552	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
553	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
554	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
555	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
556	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
557	     * The returned value is stored and returned unchanged.
558	     *
559	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
560	     * @param region   the owner's region derived from its city
561	     * @return the postcode to store, or {@code null} if none was supplied
562	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
563	     *                                     out of range for the city's region, yielding a 400 response
564	     */
565	    private String validatePostcode(String postcode, String region) {
566	        if (postcode == null) {
567	            return null;
568	        }
569	        if (!postcode.matches("[0-9]{4}")) {
570	            throw new InvalidOwnerFieldsException(List.of("postcode"));
571	        }
572	        int[] range = REGION_POSTCODES.get(region);
573	        if (range != null) {
574	            int value = Integer.parseInt(postcode);
575	            if (value < range[0] || value > range[1]) {
576	                throw new InvalidOwnerFieldsException(List.of("postcode"));
577	            }
578	        }
579	        return postcode;
580	    }
