582	    /**
583	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
584	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
585	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
586	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
587	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
588	     *
589	     * @param telephone the raw telephone value submitted by the client
590	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
591	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
592	     *                                     400 response
593	     */
594	    private String normalizeTelephone(String telephone) {
595	        String e164 = toE164(telephone);
596	        if (e164 == null) {
597	            throw new InvalidOwnerFieldsException(List.of("telephone"));
598	        }
599	        return e164;
600	    }
601	
602	    /**
603	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
604	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
605	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
606	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
607	     * and when the supplied country code is one with a known national-number length
608	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
609	     * number must have exactly that many digits.
610	     *
611	     * @param telephone the raw telephone value, possibly {@code null}
612	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
613	     */
614	    private String toE164(String telephone) {
615	        if (telephone == null) {
616	            return null;
617	        }
618	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
619	        boolean hasPlus = cleaned.startsWith("+");
620	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
621	        String nationalSignificant = hasPlus
622	            ? digits
623	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
624	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
625	            return null;
626	        }
627	        if (!hasValidNationalNumberLength(nationalSignificant)) {
628	            return null;
629	        }
630	        return "+" + nationalSignificant;
631	    }
632	
633	    /**
634	     * Checks the national-number length of an E.164 number (country code plus national significant
635	     * digits, no leading {@code '+'}) against the per-country requirement in
636	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
637	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
638	     * country code is not listed carries no per-country length requirement and is accepted.
639	     *
640	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
641	     *                            leading {@code '+'}
642	     * @return {@code true} if the national-number length is correct for the country code, or the
643	     *         country code has no listed requirement; {@code false} otherwise
644	     */
645	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
646	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
647	            .filter(nationalSignificant::startsWith)
648	            .max(Comparator.comparingInt(String::length))
649	            .orElse(null);
650	        if (countryCode == null) {
651	            return true;
652	        }
653	        int nationalLength = nationalSignificant.length() - countryCode.length();
654	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
655	    }
