657	    /**
658	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
659	     * is left unset. When a value is present it must be a syntactically valid address whose domain is
660	     * not on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the stored and
661	     * returned value is that address lower-cased.
662	     *
663	     * @param email the raw email value submitted by the client, or {@code null} if omitted
664	     * @return the lower-cased email, or {@code null} if none was supplied
665	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
666	     *                                     or its domain is a disposable-mail domain, yielding a 400
667	     *                                     response
668	     */
669	    private String normalizeEmail(String email) {
670	        if (email == null) {
671	            return null;
672	        }
673	        if (!EMAIL_PATTERN.matcher(email).matches()) {
674	            throw new InvalidOwnerFieldsException(List.of("email"));
675	        }
676	        String normalized = email.toLowerCase(Locale.ROOT);
677	        String domain = normalized.substring(normalized.indexOf('@') + 1);
678	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
679	            throw new InvalidOwnerFieldsException(List.of("email"));
680	        }
681	        return normalized;
682	    }
