684	    /**
685	     * Counts the existing owners that, before this create, already share the given first name and
686	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
687	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
688	     * been saved yet, so it is never included in the count.
689	     *
690	     * @param firstName the first name of the owner being created
691	     * @param lastName  the last name of the owner being created
692	     * @return the number of existing owners sharing both names
693	     */
694	    private int countNamesakes(String firstName, String lastName) {
695	        String normalizedFirstName = normalizeForComparison(firstName);
696	        String normalizedLastName = normalizeForComparison(lastName);
697	        return (int) this.clinicService.findAllOwners().stream()
698	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
699	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
700	            .count();
701	    }
702	
703	    /**
704	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
705	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
706	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
707	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
708	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
709	     * same postcode region, telephone and last name always yield the same customer code.
710	     *
711	     * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
712	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
713	     * it unique, so distinct owners always receive distinct customer codes.
714	     *
715	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
716	     * @param telephone the owner's normalized (E.164) telephone
717	     * @param lastName  the owner's last name
718	     * @return the formatted, de-duplicated customer code
719	     */
720	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
721	        String region = regionForPostcode(postcode);
722	        String hash8 = hashHex(telephone + lastName, 8);
723	        String baseCode = region + "-" + hash8;
724	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
725	            .map(Owner::getCustomerCode)
726	            .filter(Objects::nonNull)
727	            .collect(Collectors.toSet());
728	        if (!existingCodes.contains(baseCode)) {
729	            return baseCode;
730	        }
731	        int n = 2;
732	        while (existingCodes.contains(baseCode + "-" + n)) {
733	            n++;
734	        }
735	        return baseCode + "-" + n;
736	    }
737	
738	    /**
739	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
740	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
741	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
742	     * {@code <REGION>} segment baked into the {@code customerCode}.
743	     *
744	     * @param postcode the owner's postcode, or {@code null}
745	     * @return the region code, or {@code 'UNKNOWN'}
746	     */
747	    private String regionForPostcode(String postcode) {
748	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
749	            return "UNKNOWN";
750	        }
751	        int value = Integer.parseInt(postcode);
752	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
753	            int[] range = entry.getValue();
754	            if (value >= range[0] && value <= range[1]) {
755	                return entry.getKey();
756	            }
757	        }
758	        return "UNKNOWN";
759	    }
760	
761	    /**
762	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
763	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
764	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
765	     * region.
766	     *
767	     * @param city the owner's city
768	     * @return the region code, or {@code 'UNKNOWN'}
769	     */
770	    private String regionForCity(String city) {
771	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
772	    }
773	
774	    /**
775	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
776	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
777	     * deterministic {@code householdId} (length 12).
778	     *
779	     * @param input  the value to hash
780	     * @param length the number of leading hex characters to return
781	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
782	     */
783	    private String hashHex(String input, int length) {
784	        return HashUtils.sha256Hex(input).substring(0, length).toUpperCase(Locale.ROOT);
785	    }
786	
787	    /**
788	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
789	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
790	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
791	     * has not been saved yet, so it is never included in the count.
792	     *
793	     * @param city the city of the owner being created
794	     * @return the number of existing owners in that city
795	     */
796	    private int countOwnersInCity(String city) {
797	        String normalizedCity = normalizeForComparison(city);
798	        return (int) this.clinicService.findAllOwners().stream()
799	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
800	            .count();
801	    }
802	
803	    /**
804	     * Rejects creation of an owner whose city already contains the maximum number of owners
805	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
806	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
807	     *
808	     * @param city the city of the owner being created
809	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
810	     *                                      owners, yielding a 409 Conflict response
811	     */
812	    private void rejectCityAtCapacity(String city) {
813	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
814	            throw new OwnerCityAtCapacityException(city);
815	        }
816	    }
817	
818	    /**
819	     * Rejects creation of an owner once the given business day has already reached its daily quota
820	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
821	     * being that day — the adjusted business day the owner being created will carry — so the quota
822	     * applies per business day. The owner being created has not been saved yet, so it is never
823	     * included in the count.
824	     *
825	     * @param registrationDate the adjusted business-day registration date of the owner being created
826	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
827	     *                                         carry that registration date, yielding a
828	     *                                         429 Too Many Requests response
829	     */
830	    private void rejectDailyLimitReached(LocalDate registrationDate) {
831	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
832	            throw new DailyOwnerLimitReachedException(registrationDate);
833	        }
834	    }
835	
836	    /**
837	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
838	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
839	     *
840	     * @param registrationDate the business day to count owners for
841	     * @return the number of existing owners registered on that day
842	     */
843	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
844	        return this.clinicService.findAllOwners().stream()
845	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
846	            .count();
847	    }
848	
849	    /**
850	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
851	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
852	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
853	     * otherwise.
854	     *
855	     * @param ownerDto the owner response to flag
856	     */
857	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
858	        LocalDate today = toBusinessDay(LocalDate.now());
859	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
860	    }
861	
862	    /**
863	     * Sets the {@code capacityWarning} flag on an owner response. The flag is {@code true} when the
864	     * owner's city already holds between {@value #CITY_CAPACITY_WARNING_THRESHOLD} and
865	     * {@value #CITY_CAPACITY} minus one owners inclusive — approaching the hard {@link #CITY_CAPACITY}
866	     * limit — and {@code false} otherwise. Owners are counted per city the same way the capacity
867	     * rejection counts them ({@link #countOwnersInCity}).
868	     *
869	     * @param ownerDto the owner response to flag
870	     */
871	    private void applyCapacityWarning(OwnerDto ownerDto) {
872	        int ownersInCity = countOwnersInCity(ownerDto.getCity());
873	        ownerDto.setCapacityWarning(
874	            ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD && ownersInCity < CITY_CAPACITY);
875	    }
876	
877	    /**
878	     * Rolls a registration date forward to a business day. A date that falls on a Saturday, a Sunday
879	     * or a listed {@linkplain #PUBLIC_HOLIDAYS public holiday} is rolled forward one day at a time
880	     * until it reaches the next non-holiday weekday; a date already on a non-holiday weekday is
881	     * returned unchanged. This applies to the effective registration date whether it was supplied in
882	     * the request or defaulted to the server date, and the adjusted value is what gets stored as
883	     * {@code registrationDate} and feeds every value derived from it (such as the membership number's
884	     * year segment and the daily create-limit's per-day bucket).
885	     *
886	     * @param date the effective registration date, supplied or defaulted
887	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
888	     */
889	    private LocalDate toBusinessDay(LocalDate date) {
890	        LocalDate adjusted = date;
891	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
892	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY
893	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
894	            adjusted = adjusted.plusDays(1);
895	        }
896	        return adjusted;
897	    }
898	
899	    /**
900	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
901	     * owner's. The identity key — the SHA-256 hex digest of {@code '<normalizedTelephone>|<lowerEmail>
902	     * |<soundex(lastName)>'} — is the single value that consolidates all duplicate detection: the
903	     * previously separate telephone, email and household checks are all expressed through it. Because
904	     * the telephone is part of the key, two owners with the same last name and postcode but different
905	     * telephones have different identity keys and are both allowed (the second is a soft match); only a
906	     * whole-key match is a duplicate. The owner being created already carries its normalized telephone,
907	     * email and last name, and existing owners store the same normalized forms, so the keys are
908	     * compared directly. Owners flagged deleted are ignored.
909	     *
910	     * @param owner the owner being created, with its telephone, email and last name already set
911	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
912	     *                                         yielding a 409 Conflict response
913	     */
914	    private void rejectDuplicateIdentity(Owner owner) {
915	        String identityKey = owner.getIdentityKey();
916	        boolean inUse = this.clinicService.findAllOwners().stream()
917	            .filter(this::isNotDeleted)
918	            .map(Owner::getIdentityKey)
919	            .anyMatch(identityKey::equals);
920	        if (inUse) {
921	            throw new DuplicateOwnerIdentityException(identityKey);
922	        }
923	    }
924	
925	    /**
926	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
927	     * that is not a hard duplicate (its identity key is unique, so it has already passed
928	     * {@link #rejectDuplicateIdentity}) yet whose {@code soundex(lastName)} and postcode both match an
929	     * existing owner's. Because the telephone is part of the identity key, two owners that share a last
930	     * name and postcode but carry different telephones have different identity keys, so the second is
931	     * created as a soft match rather than rejected. When such a match exists the owner is created with
932	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
933	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
934	     * {@code false} and {@code possibleDuplicateOf} is left unset.
935	     *
936	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
937	     * declared household member is not a suspected duplicate. An owner without a postcode cannot match
938	     * on postcode and so is never flagged.
939	     *
940	     * @param owner           the owner being created, with its telephone, email, postcode and last
941	     *                        name already set
942	     * @param sharesHousehold whether the owner declared itself a member of an existing household
943	     */
944	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
945	        owner.setPossibleDuplicate(false);
946	        if (sharesHousehold) {
947	            return;
948	        }
949	        String postcode = owner.getPostcode();
950	        if (postcode == null) {
951	            return;
952	        }
953	        String soundex = owner.getLastNameSoundex();
954	        String identityKey = owner.getIdentityKey();
955	        Owner match = this.clinicService.findAllOwners().stream()
956	            .filter(this::isNotDeleted)
957	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
958	                && soundex.equals(existing.getLastNameSoundex())
959	                && postcode.equals(existing.getPostcode()))
960	            .min(Comparator.comparingInt(Owner::getId))
961	            .orElse(null);
962	        if (match != null) {
963	            owner.setPossibleDuplicate(true);
964	            owner.setPossibleDuplicateOf(match.getId());
965	        }
966	    }
967	
968	    /**
969	     * Caps the membership level of the owner being created so it cannot exceed one above the current
970	     * maximum membership level among its existing household members. A household member is a live (not
971	     * soft-deleted) owner carrying the same computed {@code householdId}. The owner's own derived level
972	     * ({@link Owner#getDerivedMembershipLevel()}) is returned capped at that maximum plus one; when the
973	     * owner belongs to no household, or no existing household member is found, no cap applies and the
974	     * derived level is returned unchanged. The owner being created has not been saved yet, so it is
975	     * never considered its own household member.
976	     *
977	     * @param owner the owner being created, with its household id and level-affecting fields set
978	     * @return the membership level to store, capped to the household ceiling where one exists
979	     */
980	    private Integer cappedMembershipLevel(Owner owner) {
981	        int derivedLevel = owner.getDerivedMembershipLevel();
982	        String householdId = owner.getHouseholdId();
983	        if (householdId == null || householdId.isBlank()) {
984	            return derivedLevel;
985	        }
986	        OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
987	            .filter(this::isNotDeleted)
988	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
989	            .mapToInt(Owner::getMembershipLevel)
990	            .max();
991	        if (maxHouseholdLevel.isEmpty()) {
992	            return derivedLevel;
993	        }
994	        return Math.min(derivedLevel, maxHouseholdLevel.getAsInt() + 1);
995	    }
996	
997	    /**
998	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
999	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
1000	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
1001	     * shares both automatically shares the same household id, so the household is keyed on
1002	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
1003	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
1004	     * still land in the same household.
1005	     *
1006	     * @param lastName the owner's last name
1007	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
1008	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
1009	     *         to no postcode-keyed household
1010	     */
1011	    private String computeHouseholdId(String lastName, String postcode) {
1012	        if (postcode == null) {
1013	            return null;
1014	        }
1015	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
1016	    }
1017	
1018	    /**
1019	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
1020	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
1021	     * the result is lower-cased.
1022	     *
1023	     * @param value the value to normalize, possibly {@code null}
1024	     * @return the normalized value, or an empty string if {@code value} is {@code null}
1025	     */
1026	    private String normalizeForComparison(String value) {
1027	        if (value == null) {
1028	            return "";
1029	        }
1030	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1031	    }
1032	
1033	    /**
1034	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
1035	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
1036	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
1037	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
1038	     * This normalized value is what gets stored and returned.
1039	     *
1040	     * @param address the raw address value submitted by the client, possibly {@code null}
1041	     * @return the normalized address, or an empty string if {@code address} is {@code null}
1042	     */
1043	    private String normalizeAddress(String address) {
1044	        if (address == null) {
1045	            return "";
1046	        }
1047	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
1048	        if (collapsed.isEmpty()) {
1049	            return collapsed;
1050	        }
1051	        String[] tokens = collapsed.split(" ");
1052	        StringBuilder normalized = new StringBuilder(collapsed.length());
1053	        for (int i = 0; i < tokens.length; i++) {
1054	            if (i > 0) {
1055	                normalized.append(' ');
1056	            }
1057	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1058	        }
1059	        return normalized.toString();
1060	    }
1061	
1062	    /**
1063	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
1064	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
1065	     * preferred when present, but either satisfies the address requirement, keeping the create
1066	     * contract backward-compatible with earlier flat-address-only owners.
1067	     *
1068	     * @param ownerFieldsDto the submitted owner fields
1069	     * @return {@code true} if an address is supplied in either form
1070	     */
1071	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
1072	        return !isBlank(ownerFieldsDto.getAddressLine1())
1073	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
1074	    }
1075	
1076	    /**
1077	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
1078	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
1079	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
1080	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
1081	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
1082	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
1083	     * working while letting everything that reads the address use the composed, normalized value.
1084	     *
1085	     * @param owner          the owner being created
1086	     * @param ownerFieldsDto the submitted owner fields
1087	     */
1088	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
1089	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
1090	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
1091	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
1092	                ? null
1093	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
1094	            owner.setAddressLine1(line1);
1095	            owner.setAddressLine2(line2);
1096	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
1097	        } else {
1098	            owner.setAddressLine1(null);
1099	            owner.setAddressLine2(null);
1100	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
1101	        }
1102	    }
1103	}
