19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Shared SHA-256 hashing helper. Generic hashing logic with no dependency on any particular domain
25	 * object, kept here so every value derived from a SHA-256 digest (the owner's {@code identityKey},
26	 * {@code householdId} and {@code customerCode} hash segment) shares one digest/hex implementation
27	 * rather than each copying the loop and its exception handling.
28	 */
29	public final class HashUtils {
30	
31	    private HashUtils() {
32	    }
33	
34	    /**
35	     * Returns the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given input. Callers
36	     * that need an upper-cased or truncated form derive it from this value.
37	     *
38	     * @param input the value to hash
39	     * @return the 64-character lower-case hex digest
40	     */
41	    public static String sha256Hex(String input) {
42	        try {
43	            byte[] digest = MessageDigest.getInstance("SHA-256")
44	                .digest(input.getBytes(StandardCharsets.UTF_8));
45	            StringBuilder hex = new StringBuilder(digest.length * 2);
46	            for (byte b : digest) {
47	                hex.append(String.format("%02x", b));
48	            }
49	            return hex.toString();
50	        } catch (NoSuchAlgorithmException e) {
51	            throw new IllegalStateException("SHA-256 algorithm not available", e);
52	        }
53	    }
54	}
