703	    /**
704	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
705	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
706	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
707	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
708	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
709	     * same postcode region, telephone and last name always yield the same customer code.
710	     *
711	     * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
712	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
713	     * it unique, so distinct owners always receive distinct customer codes.
714	     *
715	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
716	     * @param telephone the owner's normalized (E.164) telephone
717	     * @param lastName  the owner's last name
718	     * @return the formatted, de-duplicated customer code
719	     */
720	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
721	        String region = regionForPostcode(postcode);
722	        String hash8 = hashHex(telephone + lastName, 8);
723	        String baseCode = region + "-" + hash8;
724	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
725	            .map(Owner::getCustomerCode)
726	            .filter(Objects::nonNull)
727	            .collect(Collectors.toSet());
728	        if (!existingCodes.contains(baseCode)) {
729	            return baseCode;
730	        }
731	        int n = 2;
732	        while (existingCodes.contains(baseCode + "-" + n)) {
733	            n++;
734	        }
735	        return baseCode + "-" + n;
736	    }
