739	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
740	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
741	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
742	     * {@code <REGION>} segment baked into the {@code customerCode}.
743	     *
744	     * @param postcode the owner's postcode, or {@code null}
745	     * @return the region code, or {@code 'UNKNOWN'}
746	     */
747	    private String regionForPostcode(String postcode) {
748	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
749	            return "UNKNOWN";
750	        }
751	        int value = Integer.parseInt(postcode);
752	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
753	            int[] range = entry.getValue();
754	            if (value >= range[0] && value <= range[1]) {
755	                return entry.getKey();
756	            }
757	        }
758	        return "UNKNOWN";
759	    }
