763	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
764	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
765	     * region.
766	     *
767	     * @param city the owner's city
768	     * @return the region code, or {@code 'UNKNOWN'}
769	     */
770	    private String regionForCity(String city) {
771	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
772	    }
