899	    /**
900	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
901	     * owner's. The identity key — the SHA-256 hex digest of {@code '<normalizedTelephone>|<lowerEmail>
902	     * |<soundex(lastName)>'} — is the single value that consolidates all duplicate detection: the
903	     * previously separate telephone, email and household checks are all expressed through it. Because
904	     * the telephone is part of the key, two owners with the same last name and postcode but different
905	     * telephones have different identity keys and are both allowed (the second is a soft match); only a
906	     * whole-key match is a duplicate. The owner being created already carries its normalized telephone,
907	     * email and last name, and existing owners store the same normalized forms, so the keys are
908	     * compared directly. Owners flagged deleted are ignored.
909	     *
910	     * @param owner the owner being created, with its telephone, email and last name already set
911	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
912	     *                                         yielding a 409 Conflict response
913	     */
914	    private void rejectDuplicateIdentity(Owner owner) {
915	        String identityKey = owner.getIdentityKey();
916	        boolean inUse = this.clinicService.findAllOwners().stream()
917	            .filter(this::isNotDeleted)
918	            .map(Owner::getIdentityKey)
919	            .anyMatch(identityKey::equals);
920	        if (inUse) {
921	            throw new DuplicateOwnerIdentityException(identityKey);
922	        }
923	    }
924	
925	    /**
926	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
927	     * that is not a hard duplicate (its identity key is unique, so it has already passed
928	     * {@link #rejectDuplicateIdentity}) yet whose {@code soundex(lastName)} and postcode both match an
929	     * existing owner's. Because the telephone is part of the identity key, two owners that share a last
930	     * name and postcode but carry different telephones have different identity keys, so the second is
931	     * created as a soft match rather than rejected. When such a match exists the owner is created with
932	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
933	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
934	     * {@code false} and {@code possibleDuplicateOf} is left unset.
935	     *
936	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
937	     * declared household member is not a suspected duplicate. An owner without a postcode cannot match
938	     * on postcode and so is never flagged.
939	     *
940	     * @param owner           the owner being created, with its telephone, email, postcode and last
941	     *                        name already set
942	     * @param sharesHousehold whether the owner declared itself a member of an existing household
943	     */
944	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
945	        owner.setPossibleDuplicate(false);
946	        if (sharesHousehold) {
947	            return;
948	        }
949	        String postcode = owner.getPostcode();
950	        if (postcode == null) {
951	            return;
952	        }
953	        String soundex = owner.getLastNameSoundex();
954	        String identityKey = owner.getIdentityKey();
955	        Owner match = this.clinicService.findAllOwners().stream()
956	            .filter(this::isNotDeleted)
957	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
958	                && soundex.equals(existing.getLastNameSoundex())
959	                && postcode.equals(existing.getPostcode()))
960	            .min(Comparator.comparingInt(Owner::getId))
961	            .orElse(null);
962	        if (match != null) {
963	            owner.setPossibleDuplicate(true);
964	            owner.setPossibleDuplicateOf(match.getId());
965	        }
966	    }
967	
968	    /**
969	     * Caps the membership level of the owner being created so it cannot exceed one above the current
970	     * maximum membership level among its existing household members. A household member is a live (not
971	     * soft-deleted) owner carrying the same computed {@code householdId}. The owner's own derived level
972	     * ({@link Owner#getDerivedMembershipLevel()}) is returned capped at that maximum plus one; when the
973	     * owner belongs to no household, or no existing household member is found, no cap applies and the
974	     * derived level is returned unchanged. The owner being created has not been saved yet, so it is
975	     * never considered its own household member.
976	     *
977	     * @param owner the owner being created, with its household id and level-affecting fields set
978	     * @return the membership level to store, capped to the household ceiling where one exists
979	     */
980	    private Integer cappedMembershipLevel(Owner owner) {
981	        int derivedLevel = owner.getDerivedMembershipLevel();
982	        String householdId = owner.getHouseholdId();
983	        if (householdId == null || householdId.isBlank()) {
984	            return derivedLevel;
985	        }
986	        OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
987	            .filter(this::isNotDeleted)
988	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
989	            .mapToInt(Owner::getMembershipLevel)
990	            .max();
991	        if (maxHouseholdLevel.isEmpty()) {
992	            return derivedLevel;
993	        }
994	        return Math.min(derivedLevel, maxHouseholdLevel.getAsInt() + 1);
995	    }
