    int sum = 0;
    boolean dbl = true;
    for (int i = this.customerCode.length() - 1; i >= 0; i--) {
        char c = this.customerCode.charAt(i);
        if (c < '0' || c > '9') {
            continue;
        }
        int d = c - '0';
        if (dbl) {
            d *= 2;
            if (d > 9) {
                d -= 9;
            }
        }
        sum += d;
        dbl = !dbl;
    }
    return (10 - (sum % 10)) % 10;
